{
  "primary_meaning": "God's righteous judgment on human wickedness and the merciful salvation of a faithful remnant via the ark",
  "primary_basis": [
    "Genesis 6–9",
    "Matthew 24:37–39",
    "Luke 17:26–27",
    "2 Peter 2:5",
    "2 Peter 3:5–7",
    "Hebrews 11:7"
  ],
  "alternatives": [
    {
      "meaning": "Typological prefiguration of Christian baptism (waters of judgment that also cleanse, ark as Church/Christ)",
      "basis": [
        "1 Peter 3:20–21"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Foreshadowing of eschatological final judgment at Christ's return",
      "basis": [
        "Matthew 24:37–39",
        "2 Peter 3:5–7"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Sign of divine covenant faithfulness and promise never again to destroy the earth by flood (rainbow)",
      "basis": [
        "Genesis 9:8–17"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Re-creation motif restoring order from chaos after primordial waters",
      "basis": [
        "Genesis 1 and 6–9 parallels",
        "Psalm 29",
        "Psalm 104"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "Primarily moral or legendary tale without strong typological weight",
      "basis": [],
      "prominence": "rare"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "Across historic Protestant, Catholic, and Orthodox teaching the Flood functions first as historical judgment-salvation narrative that supplies the dominant typology; baptismal and eschatological readings are widespread secondary applications rather than rivals."
}
